"  void _recalculateYRangeForVisibleX(double xMin, double xMax, List<CandleModel> candles) {
    if (candles.isEmpty || _isManualYScale) return;

    int startIndex = xMin.round().clamp(0, candles.length - 1);
    int endIndex = xMax.round().clamp(0, candles.length - 1);

    if (startIndex > endIndex) {
      final temp = startIndex;
      startIndex = endIndex;
      endIndex = temp;
    }

    double minLow = double.infinity;
    double maxHigh = -double.infinity;

    for (int i = startIndex; i <= endIndex; i++) {
      final c = candles[i];
      if (c.low < minLow) minLow = c.low;
      if (c.high > maxHigh) maxHigh = c.high;
    }

    if (minLow == double.infinity || maxHigh == -double.infinity) return;

    final range = maxHigh - minLow;
    final padding = range > 0 ? range * 0.08 : minLow * 0.01;
    final newMin = minLow - padding;
    final double newMax = maxHigh + padding;

    final isSignificant = _yVisibleMin == null || 
        _yVisibleMax == null || 
        (newMin - _yVisibleMin!).abs() > (minLow * 0.0005) || 
        (newMax - _yVisibleMax!).abs() > (maxHigh * 0.0005);

    if (isSignificant) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && !_isManualYScale) {
          setState(() {
            _yVisibleMin = newMin;
            _yVisibleMax = newMax;
          });
        }
      });
    }
  }
